use super::types::JournalWriteBatch;
use crate::codec::encode_record;
use crate::constants::{
    MAGIC_BLOB, MAGIC_COMPILED_ARTIFACT, MAGIC_INDEX_RECORD, MAGIC_WORKFLOW_SOURCE, MAX_BLOB_BYTES,
    MAX_COMPILED_IR_BYTES, MAX_RUN_HEADER_BYTES, MAX_WORKFLOW_SOURCE_BYTES,
