            MAGIC_SNAPSHOT,
            RecordKind::Snapshot,
            snapshot.seq.get(),
            snapshot,
            MAX_SNAPSHOT_BYTES,
        ) {
            Ok(v) => v,
            Err(e) => {
                self.aborted = true;
                return Err(e);
            }
        };
        self.inner.insert(&self.journal.run_snapshot, key, value);
        Ok(())
    }

