        let run = RunId::new(run_val);
        let step = StepIdx::new(step_val);
        let (_temp, journal) = temp_journal();

        let event_a = make_action_scheduled(run, seq_a, step, action);
        let event_b = make_action_scheduled(run, seq_b, step, action);

