// ---------------------------------------------------------------------------
// PO-012: len() is strictly monotonic; is_empty() == (len() == 0) (proptest)
// ---------------------------------------------------------------------------

proptest::proptest! {
    #![proptest_config(journal_proptest_config(JOURNAL_IO_PROPTEST_CASES))]

    /// PO-012: After N successful staging operations, batch.len() ==
    /// num_appends * 2 (each action-scheduled event auto-stages the
    /// matching index_action mutation). `is_empty()` ==
    /// `(len() == 0)` always holds.
    ///
    /// vb-3wn7x: as of this fix, each `append_event(ActionScheduled)`
    /// appends the event AND its `index_action` mutation to the
    /// OwnedWriteBatch, so each successful `append_event` increments
    /// `batch.len()` by exactly 2 (event row + index marker). The
    /// total `batch.len()` after `N` appends is therefore `N * 2`,
    /// not `N`. The strict-monotonicity, `is_empty() == (len() == 0)`,
    /// and never-shrinks invariants remain.
    #[test]
    fn test_batch_len_monotonic_and_is_empty_invariant(
        num_ops in 0u8..=20u8,
        action_val in 1u16..=100u16,
        run_val in 1u64..=1000u64,
    ) {
        // vb-3wn7x: one for the event row + one for the auto-staged
        // index_action mutation. Future action-lifecycle variants that
        // stage additional index mutations would bump this constant.
        const LEN_INCREMENT_PER_APPEND_EVENT: usize = 2;

        let action = ActionId::new(action_val);
        let run = RunId::new(run_val);
        let (_temp, journal) = temp_journal();

        let mut batch = JournalWriteBatch::new(&journal);

        // Initial state invariants
        prop_assert_eq!(batch.len(), 0, "new batch len must be 0");
        prop_assert!(batch.is_empty(), "new batch must be empty");

        let num_ops = num_ops as usize;
        for i in 0..num_ops {
            let step = StepIdx::new(i as u16);
            let event = make_action_scheduled(run, i as u64, step, action);

            let before_len = batch.len();
            let _before_empty = batch.is_empty();

            let result = batch.append_event(&event);
            prop_assert!(result.is_ok(), "append_event must succeed for valid event");

            // After successful staging: len increases by the per-call
            // increment (event + auto-staged index_action).
            prop_assert_eq!(
                batch.len(),
                before_len + LEN_INCREMENT_PER_APPEND_EVENT,
                "len must increment by 2 after successful staging (event + auto-staged index_action)",
            );
            prop_assert!(
                batch.len() > before_len,
                "len must be strictly greater after successful staging",
            );
            prop_assert!(
                !batch.is_empty(),
                "batch must not be empty after successful staging",
            );

            // is_empty == (len == 0) invariant must always hold
            prop_assert_eq!(
                batch.is_empty(),
                batch.len() == 0,
                "is_empty() must equal (len() == 0) always",
            );
        }

        // After all staging: len == num_ops * 2 (each append_event
        // contributes the event row plus the auto-staged index_action
        // mutation).
        prop_assert_eq!(
            batch.len(),
            num_ops * LEN_INCREMENT_PER_APPEND_EVENT,
            "final len must equal num_ops * 2 (each append contributes event + index)",
        );
        prop_assert_eq!(
            batch.is_empty(),
            num_ops == 0,
            "is_empty must be true iff num_ops == 0",
        );
    }
}

// ---------------------------------------------------------------------------
// PO-013: Once aborted==true, commit reports BatchAborted (proptest)
// ---------------------------------------------------------------------------

proptest::proptest! {
    #![proptest_config(journal_proptest_config(JOURNAL_IO_PROPTEST_CASES))]

    /// PO-013: After first op triggers abort, subsequent ops may return Ok(()),
    /// but commit() reports the abort and persists none of the aborted batch.
    ///
    /// The abort condition is triggered by a duplicate event (same run, same seq).
    /// Once aborted, len()/is_empty() expose no committable staged state.
    #[test]
    fn test_aborted_gate_blocks_subsequent_staging(
        action_val in 1u16..=100u16,
        run_val in 1u64..=1000u64,
        step_val in 0u16..=50u16,
        // Number of subsequent ops attempted after abort
        num_subsequent in 1u8..=5u8,
    ) {
        let action = ActionId::new(action_val);
        let run = RunId::new(run_val);
        let step = StepIdx::new(step_val);
        let (_temp, journal) = temp_journal();

        // Pre-commit the first event so it exists in the journal
        let event = make_action_scheduled(run, 0, step, action);
        {
            let mut setup_batch = JournalWriteBatch::new(&journal);
            setup_batch.append_event(&event).expect("setup append must succeed");
            setup_batch.commit().expect("setup commit must succeed");
        }

        // Now create a new batch and trigger abort with duplicate event
        let mut batch = JournalWriteBatch::new(&journal);

        // First staging op: duplicate event triggers abort
        let dup_result = batch.append_event(&event);
        // append_event returns Err(DuplicateEvent) and sets aborted=true
        prop_assert!(
            matches!(dup_result, Err(JournalError::DuplicateEvent { .. })),
            "duplicate event must return DuplicateEvent error",
        );
        prop_assert!(batch.is_aborted(), "duplicate event must mark batch aborted");

        // After abort: len must be 0 and batch must be empty
        prop_assert_eq!(batch.len(), 0, "len must be 0 after aborted duplicate event");
        prop_assert!(batch.is_empty(), "batch must be empty after abort");

        // Attempt num_subsequent staging ops
        let num_subsequent = num_subsequent as usize;
        for i in 0..num_subsequent {
            let seq = (i + 10) as u64;
            let subsequent_event = make_action_scheduled(run, seq, step, action);

            let before_len = batch.len();
            let subsequent_result = batch.append_event(&subsequent_event);

            // After abort: subsequent ops may return Ok(()), but there is no
            // committable state and commit remains BatchAborted.
            prop_assert!(
                subsequent_result.is_ok(),
                "after abort, append_event may return Ok",
            );
            prop_assert_eq!(
                batch.len(),
                before_len,
                "after abort, len must not increase",
            );
        }

        // commit() on aborted batch reports the abort and persists no staged data.
        let commit_result = batch.commit();
        prop_assert!(
            matches!(&commit_result, Err(JournalError::BatchAborted)),
            "commit on aborted batch must return BatchAborted, got {:?}",
            commit_result,
        );

        // After aborted commit: journal must be unchanged (only original event exists)
        let events = journal.events_for_run(run).expect("events_for_run must succeed");
        prop_assert_eq!(
            events.len(),
            1,
            "aborted batch must not write any new events",
        );
        prop_assert_eq!(&events[0], &event, "only original event must remain");
    }
}

